//! Shared consensus vectors. `tests/vectors/consensus_v1.json` is generated by the node
//! implementation (`network-common`'s `tests/consensus_vectors.rs`) and copied here by the sync.
//! This crate is a clean-room re-implementation, so it must reproduce every byte of every case.
//! Never edit the file by hand: a mismatch means this crate drifted from the node.

use filament_types::beacon_wire_header::WireBeaconHeader;
use filament_types::hash::{hash_pair, sha256d};
use filament_types::merged_mining_hash::MergedMiningHash;
use filament_types::pow_target::{hash_meets_target, rbits_to_target};
use filament_types::hash_sorting::{extract_sorting_bits, find_eligible_shard};
use filament_types::mmr_math::{
    fork_path_positions, genesis_mmr_root, peak_descriptors, replay_peaks_after_appends,
};
use filament_types::relay_hash::relay_id;
use filament_types::tx_sighash::{prevouts_hash, sighash_v2};
use filament_types::txid::txid_from_parts;
use filament_types::weighted_hash::{
    bag_peaks_weighted_u128, hash_pair_weighted, rbits_add, rbits_to_u128_approx, u128_to_rbits,
    WeightedHash,
};
use filament_types::weighted_mmr_peaks::WeightedMMR;
use serde_json::Value;

const VECTORS: &str = include_str!("vectors/consensus_v1.json");

fn h(b: &[u8]) -> String {
    hex::encode(b)
}
fn hv(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().expect("hex string")).expect("hex")
}
fn from_h32(v: &Value) -> [u8; 32] {
    hv(v).try_into().expect("32 bytes")
}
fn wh(raw: [u8; 32]) -> WeightedHash {
    WeightedHash::from(raw)
}
fn dec(v: &Value) -> u128 {
    v.as_str().expect("decimal string").parse().expect("u128")
}
fn peaks_of(v: &Value) -> Vec<WeightedHash> {
    v.as_array().unwrap().iter().map(|p| wh(from_h32(p))).collect()
}

#[test]
fn every_shared_vector_matches() {
    let v: Value = serde_json::from_str(VECTORS).expect("vectors parse");
    assert_eq!(v["format"], 1);

    for c in v["sha256d"].as_array().unwrap() {
        assert_eq!(h(&sha256d(&hv(&c["data"]))), c["out"].as_str().unwrap());
    }
    for c in v["hash_pair"].as_array().unwrap() {
        assert_eq!(h(&hash_pair(&from_h32(&c["left"]), &from_h32(&c["right"]))), c["out"].as_str().unwrap());
    }
    let w = &v["weighted_hash"];
    for c in w["from_leaf_rbits"].as_array().unwrap() {
        let out = WeightedHash::from_leaf_rbits(&from_h32(&c["hash"]), c["rbits"].as_u64().unwrap() as u32);
        assert_eq!(h(out.raw()), c["out"].as_str().unwrap());
    }
    for c in w["from_anchor"].as_array().unwrap() {
        assert_eq!(h(WeightedHash::from_anchor(&from_h32(&c["hash"])).raw()), c["out"].as_str().unwrap());
    }
    for c in w["hash_pair_weighted"].as_array().unwrap() {
        let out = hash_pair_weighted(&wh(from_h32(&c["left"])), &wh(from_h32(&c["right"])));
        assert_eq!(h(out.raw()), c["out"].as_str().unwrap());
    }
    for c in w["rbits_add"].as_array().unwrap() {
        assert_eq!(rbits_add(c["a"].as_u64().unwrap() as u32, c["b"].as_u64().unwrap() as u32) as u64, c["out"].as_u64().unwrap());
    }
    for c in w["u128_to_rbits"].as_array().unwrap() {
        assert_eq!(u128_to_rbits(dec(&c["difficulty"])) as u64, c["out"].as_u64().unwrap());
    }
    for c in w["rbits_to_u128_approx"].as_array().unwrap() {
        assert_eq!(rbits_to_u128_approx(c["rbits"].as_u64().unwrap() as u32), dec(&c["out"]));
    }
    for c in w["bag_peaks_u128"].as_array().unwrap() {
        let (root, weight) = bag_peaks_weighted_u128(&peaks_of(&c["peaks"]), wh(from_h32(&c["anchor"])));
        assert_eq!(h(root.raw()), c["root"].as_str().unwrap());
        assert_eq!(weight, dec(&c["weight"]));
    }
    for c in w["peaks_after_append"].as_array().unwrap() {
        let (np, root, weight) = WeightedMMR::compute_peaks_after_append(
            &peaks_of(&c["peaks"]),
            c["leaf_count_before"].as_u64().unwrap() as u32,
            wh(from_h32(&c["leaf"])),
            wh(from_h32(&c["anchor"])),
        );
        let want: Vec<String> = c["new_peaks"].as_array().unwrap().iter().map(|p| p.as_str().unwrap().to_string()).collect();
        assert_eq!(np.iter().map(|p| h(p.raw())).collect::<Vec<_>>(), want);
        assert_eq!(h(root.raw()), c["root"].as_str().unwrap());
        assert_eq!(weight, dec(&c["weight"]));
    }
    for c in v["hash_sorting"].as_array().unwrap() {
        let x = hv(&c["hash"]);
        let k = c["k"].as_u64().unwrap() as u32;
        assert_eq!(extract_sorting_bits(&x, k) as u64, c["bits"].as_u64().unwrap());
        assert_eq!(find_eligible_shard(&x, k).map(|s| s as u64), c["shard"].as_u64());
    }
    for c in v["sighash"]["prevouts_hash"].as_array().unwrap() {
        let list: Vec<(u64, [u8; 32])> = c["prevouts"].as_array().unwrap().iter()
            .map(|p| (p[0].as_u64().unwrap(), from_h32(&p[1]))).collect();
        assert_eq!(h(&prevouts_hash(&list)), c["out"].as_str().unwrap());
    }
    for c in v["sighash"]["sighash_v2"].as_array().unwrap() {
        let out = sighash_v2(&from_h32(&c["txid"]), &from_h32(&c["prevouts_hash"]), c["input_index"].as_u64().unwrap() as u32);
        assert_eq!(h(&out), c["out"].as_str().unwrap());
    }
    for c in v["txid"].as_array().unwrap() {
        let inputs: Vec<(u32, u16)> = c["inputs"].as_array().unwrap().iter()
            .map(|p| (p[0].as_u64().unwrap() as u32, p[1].as_u64().unwrap() as u16)).collect();
        let outputs: Vec<(u64, [u8; 32])> = c["outputs"].as_array().unwrap().iter()
            .map(|p| (p[0].as_u64().unwrap(), from_h32(&p[1]))).collect();
        let payloads: Vec<Vec<u8>> = c["extensions"].as_array().unwrap().iter().map(|e| hv(&e[2])).collect();
        let exts: Vec<(u16, u16, &[u8])> = c["extensions"].as_array().unwrap().iter().zip(&payloads)
            .map(|(e, p)| (e[0].as_u64().unwrap() as u16, e[1].as_u64().unwrap() as u16, p.as_slice())).collect();
        let out = txid_from_parts(
            c["chain_id"].as_u64().unwrap() as u16,
            c["version"].as_u64().unwrap() as u8,
            c["locktime"].as_u64().unwrap() as u32,
            c["expiration_height"].as_u64().unwrap() as u32,
            &inputs, &outputs, &exts,
        );
        assert_eq!(h(&out), c["out"].as_str().unwrap());
    }
    let mm = &v["merged_mining_hash"];
    for c in mm["leaves"].as_array().unwrap() {
        assert_eq!(h(MergedMiningHash::from_active_leaf(&from_h32(&c["shard_hash"])).raw()), c["out"].as_str().unwrap());
    }
    for c in mm["combines"].as_array().unwrap() {
        let levels = c["levels"].as_array().unwrap();
        let mut cur: Vec<MergedMiningHash> = levels[0].as_array().unwrap().iter().map(|x| MergedMiningHash::from(from_h32(x))).collect();
        for want in &levels[1..] {
            cur = cur.chunks(2).map(|p| MergedMiningHash::combine(&p[0], &p[1])).collect();
            let got: Vec<String> = cur.iter().map(|x| h(x.raw())).collect();
            let want: Vec<String> = want.as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
            assert_eq!(got, want);
        }
    }
    for c in mm["parts"].as_array().unwrap() {
        let prefix: [u8; 30] = hv(&c["prefix"]).try_into().unwrap();
        let x = MergedMiningHash::from_parts(&prefix, c["tree_height"].as_u64().unwrap() as u8, c["chain_count"].as_u64().unwrap() as u16);
        assert_eq!(h(x.raw()), c["out"].as_str().unwrap());
        assert_eq!(MergedMiningHash::chain_count_of_root(x.raw()) as u64, c["root_chain_count"].as_u64().unwrap());
        assert_eq!(MergedMiningHash::tree_height_of_root(x.raw()) as u64, c["root_tree_height"].as_u64().unwrap());
        let swapped = MergedMiningHash::root_with_chain_count(*x.raw(), c["swapped_count"].as_u64().unwrap() as u16);
        assert_eq!(h(&swapped), c["swapped"].as_str().unwrap());
    }
    for c in v["pow_target"]["targets"].as_array().unwrap() {
        let got = rbits_to_target(c["rbits"].as_u64().unwrap() as u32, &from_h32(&c["initial"]), c["s"].as_u64().unwrap() as u32);
        assert_eq!(h(&got), c["out"].as_str().unwrap());
    }
    for c in v["pow_target"]["meets"].as_array().unwrap() {
        assert_eq!(hash_meets_target(&from_h32(&c["hash"]), &from_h32(&c["target"])), c["out"].as_bool().unwrap());
    }
    let m = &v["mmr_math"];
    for c in m["peak_descriptors"].as_array().unwrap() {
        let got: Vec<Vec<u64>> = peak_descriptors(c["leaf_count"].as_u64().unwrap() as u32)
            .iter().map(|(p, hh)| vec![*p as u64, *hh as u64]).collect();
        let want: Vec<Vec<u64>> = c["peaks"].as_array().unwrap().iter()
            .map(|p| vec![p[0].as_u64().unwrap(), p[1].as_u64().unwrap()]).collect();
        assert_eq!(got, want);
    }
    for c in m["replay_peaks_after_appends"].as_array().unwrap() {
        let leaves: Vec<WeightedHash> = c["leaves"].as_array().unwrap().iter().map(|p| wh(from_h32(p))).collect();
        let got = replay_peaks_after_appends(&peaks_of(&c["base_peaks"]), c["base_leaf_count"].as_u64().unwrap() as u32, &leaves);
        let want: Vec<Vec<String>> = c["after"].as_array().unwrap().iter()
            .map(|ps| ps.as_array().unwrap().iter().map(|p| p.as_str().unwrap().to_string()).collect()).collect();
        let got: Vec<Vec<String>> = got.iter().map(|ps| ps.iter().map(|p| h(p.raw())).collect()).collect();
        assert_eq!(got, want);
    }
    for c in m["genesis_mmr_root"].as_array().unwrap() {
        assert_eq!(h(genesis_mmr_root(&from_h32(&c["anchor_hash"]), wh(from_h32(&c["leaf"]))).raw()), c["out"].as_str().unwrap());
    }
    for c in m["fork_path_positions"].as_array().unwrap() {
        let got: Vec<Vec<u64>> = fork_path_positions(c["from"].as_u64().unwrap() as u32, c["to"].as_u64().unwrap() as u32)
            .iter().map(|(i, l)| vec![*i as u64, *l as u64]).collect();
        let want: Vec<Vec<u64>> = c["positions"].as_array().unwrap().iter()
            .map(|p| vec![p[0].as_u64().unwrap(), p[1].as_u64().unwrap()]).collect();
        assert_eq!(got, want);
    }
    for c in v["relay_id"].as_array().unwrap() {
        assert_eq!(h(&relay_id(&hv(&c["payload"]))), c["out"].as_str().unwrap());
    }
    for c in v["wire_beacon_header"].as_array().unwrap() {
        let hd = WireBeaconHeader {
            version: c["version"].as_u64().unwrap() as u32,
            prev_mmr_root: wh(from_h32(&c["prev_mmr_root"])),
            delta: c["delta"].as_i64().unwrap() as i32,
            bits: c["bits"].as_u64().unwrap() as u32,
            nonce: c["nonce"].as_u64().unwrap() as u32,
            height: c["height"].as_u64().unwrap() as u32,
            tx_merkle_root: from_h32(&c["tx_merkle_root"]),
            merged_mining_root: from_h32(&c["merged_mining_root"]),
            coinbase_hash: from_h32(&c["coinbase_hash"]),
        };
        assert_eq!(hd.root_chain_count() as u64, c["chain_count"].as_u64().unwrap());
        assert_eq!(h(&hd.serialize()), c["serialized"].as_str().unwrap());
        assert_eq!(WireBeaconHeader::deserialize(&hv(&c["serialized"])).unwrap(), hd);
        assert_eq!(h(&hd.commitment_hash()), c["commitment"].as_str().unwrap());
        assert_eq!(h(&hd.pow_hash()), c["pow_hash"].as_str().unwrap());
    }
}
